    let 归笺 = Number(readB("筱筱吖/娱乐系统/游戏数据/归笺.json", event.user_id, 0));
    let 银行归笺 = Number(readB("筱筱吖/娱乐系统/游戏数据/银行系统/银行归笺.json", event.user_id, 0));
