  let 视频解析临时文件序号 = 0;
  async function 视频解析探测体积(url, timeoutMs = 15e3) {
    const 单次 = async (method, extraHeaders) => {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), Math.max(3e3, Number(timeoutMs) || 15e3));
      try {
        const 代理F = mkUrlNeedsProxy(url) ? await mkEnsureProxiedFetch() : null;
        const res = await (代理F || fetch)(url, {
          method,
          headers: { ...mkBuildDownloadHeaders(url), ...extraHeaders || {} },
          signal: controller.signal
        });
        try {
          await res.body?.cancel?.();
        } catch {
        }
        if (!res.ok && res.status !== 206) return null;
        const range = res.headers.get("content-range");
        const 总长 = String(range || "").match(/\/(\d+)\s*$/);
        if (总长) return Number(总长[1]);
        if (!extraHeaders?.Range) {
          const len = Number(res.headers.get("content-length"));
          if (Number.isFinite(len) && len > 0) return len;
        }
        return null;
      } catch {
        return null;
      } finally {
        clearTimeout(timer);
      }
    };
    const byHead = await 单次("HEAD");
    if (byHead != null) return byHead;
    return await 单次("GET", { Range: "bytes=0-0" });
  }
  function 视频解析安全文件名(name, fallback = "media") {
    return String(name || fallback).replace(/[^\w\u4e00-\u9fff\-]+/g, "_").replace(/^_+|_+$/g, "").slice(0, 40) || fallback;
  }
  function 视频解析取音频链接(music) {
    if (!music) return "";
    if (typeof music === "string") {
      const s = music.trim();
      return /^https?:\/\//i.test(s) ? s : "";
    }
    if (typeof music === "object") {
      for (const key of ["url", "playUrl", "play_url", "uri"]) {
        const v = music[key];
        if (typeof v === "string" && /^https?:\/\//i.test(v.trim())) return v.trim();
        if (v && typeof v === "object") {
          const nested = v.uri || v.url || (Array.isArray(v.url_list) ? v.url_list[0] : "") || (Array.isArray(v.urlList) ? v.urlList[0] : "");
          if (typeof nested === "string" && /^https?:\/\//i.test(nested.trim())) return nested.trim();
        }
      }
    }
    return "";
  }
  function 视频解析音频展示名(music, title) {
    if (music && typeof music === "object") {
      const n = String(music.title || music.name || "").trim();
      if (n) return `${视频解析安全文件名(n, "audio")}.mp3`;
    }
    return `${视频解析安全文件名(title, "audio")}.mp3`;
  }
  async function 视频解析下载临时文件(url, {
    ext = ".bin",
    basename = "media",
    maxBytes = MK_VIDEO_SEND_MAX_BYTES,
    timeoutMs = 0,
    cleanup = null,
    // probe=false：跳过下载前的 HEAD 体积探测，直接下，下完再按 maxBytes 复检。
    // 图片/封面这类小文件探测是纯亏 —— 实测一个 0.0MB 的封面光探测就花 0.6~4.2s，
    // 而它本身有 20MB 上限兜底，边下边判超限即可。视频/音频仍要探测：
    // 它们动辄几十 MB，早停能省下整段白跑（60MB 约 140 秒）。
    probe = true
  } = {}) {
    const src = String(url || "").trim();
    if (!src) return { ok: false };
    const 临时目录 = mkGetTempVideoDir();
    try {
      fs.mkdirSync(临时目录, { recursive: true });
    } catch {
      return { ok: false };
    }
    const t0 = Date.now();
    const 远端体积 = probe ? await 视频解析探测体积(src, Math.min(15e3, timeoutMs || 15e3)) : null;
    if (远端体积 != null && 远端体积 > maxBytes) {
      return { ok: false, tooLarge: true, size: 远端体积 };
    }
    if (!shouldDownloadMediaForSend(远端体积)) {
      return { ok: false, skippedUnsendable: true, size: 远端体积 };
    }
    视频解析临时文件序号 += 1;
    const 本地路径 = path.join(
      临时目录,
      `${Date.now()}_${视频解析临时文件序号}_${视频解析安全文件名(basename)}.${String(ext).replace(/^\./, "")}`
    );
    try {
      const downloaded = await downloadFile(src, 本地路径, true, timeoutMs);
      if (!downloaded || !fs.existsSync(本地路径)) {
        视频解析清理本地文件(本地路径);
        return { ok: false };
      }
      const 体积 = fs.existsSync(本地路径) ? fs.statSync(本地路径).size : 0;
      if (体积 > maxBytes) {
        视频解析清理本地文件(本地路径);
        return { ok: false, tooLarge: true, size: 体积 };
      }
      if (Array.isArray(cleanup)) cleanup.push(本地路径);
      const 耗时 = Date.now() - t0;
      if (耗时 >= 500) {
        logger?.info?.(`[视频解析] 下载完成 ${(体积 / 1048576).toFixed(1)}MB 耗时 ${耗时}ms`);
      }
      return { ok: true, path: 本地路径 };
    } catch {
      视频解析清理本地文件(本地路径);
      return { ok: false };
    }
  }
