  function mkStripMissingMediaFromNodes(list) {
    const 媒体类型 = ["image", "video", "record", "voice", "file", "audio"];
    let 剔除 = 0;
    const out = [];
    for (const node of list) {
      const content = node?.data?.content ?? node?.data?.message;
      if (!Array.isArray(content)) {
        out.push(node);
        continue;
      }
      const kept = content.filter((seg) => {
        if (!seg || typeof seg !== "object" || !seg.data) return true;
        const type = String(seg.type || "");
        if (!媒体类型.includes(type)) return true;
        const f = String(seg.data?.file ?? "");
        if (!/^file:\/\//i.test(f)) return true;
        let p = "";
        try {
          p = fileURLToPath(f);
        } catch {
          return true;
        }
        try {
          if (fs.existsSync(p)) return true;
        } catch {
          return true;
        }
        剔除 += 1;
        return false;
      });
      if (!kept.length) continue;
      out.push({ ...node, data: { ...node?.data || {}, content: kept } });
    }
    if (剔除) logger?.warn?.(`[视频解析] ${剔除} 个媒体文件已失效（可能被提前清理），已从合并转发中剔除`);
    return out;
  }
  async function 视频解析发出合并转发(event2, ctx2, {
    platform,
    title = "",
    nodes
  }) {
    let list = Array.isArray(nodes) ? nodes.filter(Boolean) : [];
    if (!list.length) return false;
    list = mkStripMissingMediaFromNodes(list);
    if (!list.length) {
      logger?.warn?.(`[视频解析] ${platform} 合并转发节点全部媒体失效，放弃发送`);
      return false;
    }
    const 每条上限 = 10;
    const 最多条数 = 4;
    const 并行开关 = String(readB("config.json", "图集并行拆分", "")).trim().toLowerCase();
    const 并行启用 = !["", "0", "false", "off", "no", "关闭"].includes(并行开关);
    if (list.length <= 每条上限 || !并行启用) {
      return await 发合并消息(
        event2,
        list,
        合并预览("视频解析", platform, "[视频解析]", [String(title || platform || "视频解析")])
      );
    }
    const 条数 = Math.min(最多条数, Math.ceil(list.length / 每条上限));
    const 每条节点 = Math.ceil(list.length / 条数);
    const chunks = [];
    for (let i = 0; i < list.length; i += 每条节点) {
      chunks.push(list.slice(i, i + 每条节点));
    }
    logger?.info?.(
      `[视频解析] ${platform} 图集 ${list.length} 节点拆成 ${chunks.length} 条并行上传（提升协议端上传并发）`
    );
    const results = await Promise.all(chunks.map((chunk, idx) => {
      const 序号 = chunks.length > 1 ? `[${idx + 1}/${chunks.length}]` : "";
      const preview = 合并预览(
        "视频解析",
        platform,
        `[视频解析]${序号}`,
        [String(title || platform || "视频解析")]
      );
      return 发合并消息(event2, chunk, preview);
    }));
    return results.some(Boolean);
  }
