async function mkFetchSnowLumaJoinComment(ctx, groupId, userId) {
  const gid = Number(groupId ?? 0);
  const uid = Number(userId ?? 0);
  if (!Number.isFinite(gid) || gid <= 0) return { found: false };
  if (!Number.isFinite(uid) || uid <= 0) return { found: false };
  try {
    const res = await BOTAPI(ctx, "get_group_system_msg", {
      group_id: gid,
      only_pending: false,
      count: 50
    });
    const list = Array.isArray(res) ? res : Array.isArray(res?.data) ? res.data : Array.isArray(res?.messages) ? res.messages : null;
    if (!Array.isArray(list) || list.length === 0) return { found: false };
    let 命中 = null;
    for (const item of list) {
      if (!item || typeof item !== "object") continue;
      const 项群号 = Number(item.group_id ?? item.groupId ?? 0);
      const 项QQ = Number(item.requester_uin ?? item.requesterUin ?? item.user_id ?? 0);
      if (项群号 !== gid || 项QQ !== uid) continue;
      if (item.checked === false) {
        命中 = item;
        break;
      }
      if (!命中) 命中 = item;
    }
    if (!命中) return { found: false };
    const comment = String(命中.message ?? 命中.comment ?? "").trim();
    const flag = String(命中.flag ?? "").trim();
    return { found: true, comment, flag: flag || null };
  } catch (e) {
    logger?.warn?.("[MKbot] SnowLuma 补齐加群留言失败:", e?.message || e);
    return { found: false };
  }
}
